CREATE TABLE IF NOT EXISTS migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, migration TEXT UNIQUE NOT NULL, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'staf', is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS locations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS asset_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, type TEXT NOT NULL CHECK(type IN ('PC','Perangkat')), category_id INTEGER REFERENCES asset_categories(id), location_id INTEGER REFERENCES locations(id), name TEXT NOT NULL, brand TEXT, model TEXT, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity > 0), status TEXT NOT NULL DEFAULT 'Baik', physical_condition TEXT NOT NULL DEFAULT 'Baik', notes TEXT, archived_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pc_details (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER UNIQUE NOT NULL REFERENCES assets(id) ON DELETE CASCADE, pc_name TEXT UNIQUE NOT NULL, ip_address TEXT, processor TEXT, ram_gb INTEGER, storage_type TEXT, storage_value TEXT, os TEXT, os_version TEXT, monitor_condition TEXT, peripheral_condition TEXT, last_checked_at TEXT, last_os_update_at TEXT);
CREATE TABLE IF NOT EXISTS software (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, category TEXT, version TEXT, size TEXT, status TEXT NOT NULL DEFAULT 'Terinstall', purpose TEXT, target_remove_at TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, number TEXT UNIQUE NOT NULL, title TEXT NOT NULL, description TEXT, instructions TEXT, category TEXT, priority TEXT NOT NULL DEFAULT 'Sedang', estimate_minutes INTEGER, assignee_id INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'Draft', due_at TEXT, taken_at TEXT, completed_at TEXT, result TEXT, revision_note TEXT, created_by INTEGER REFERENCES users(id), verified_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS task_assets (task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, asset_id INTEGER NOT NULL REFERENCES assets(id), PRIMARY KEY(task_id,asset_id));
CREATE TABLE IF NOT EXISTS inspections (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL REFERENCES assets(id), inspector_id INTEGER REFERENCES users(id), inspected_at TEXT NOT NULL, condition_before TEXT, condition_after TEXT, findings TEXT, affected_count INTEGER NOT NULL DEFAULT 0, followup_task_id INTEGER REFERENCES tasks(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, event_date TEXT NOT NULL, location_id INTEGER REFERENCES locations(id), status TEXT NOT NULL DEFAULT 'Belum Siap', notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_assets_status_location ON assets(status,location_id);
CREATE INDEX IF NOT EXISTS idx_tasks_status_assignee_due ON tasks(status,assignee_id,due_at);
CREATE INDEX IF NOT EXISTS idx_inspections_asset_date ON inspections(asset_id,inspected_at);

